    public Object parseTrade(Object trade, Object... optionalArgs)
    {
        //
        // public fetchTrades
        //
        //     {
        //         "amount":0.00102091,
        //         "rate":21549.09999991,
        //         "total":21.99969168,
        //         "coin":"BTC",
        //         "solddate":1604890646143,
        //         "market":"BTC/AUD"
        //     }
        //
        // private fetchMyTrades
        //     {
        //       "otc": false,
        //       "market": "ALGO/AUD",
        //       "amount": 386.95197925,
        //       "created": "2022-10-20T09:56:44.502Z",
        //       "audfeeExGst": 1.80018002,
        //       "audGst": 0.180018,
        //       "audtotal": 200,
        //       "total": 200,
        //       "side": "buy",
        //       "price": 0.5168600000125209
        //     }
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object timestamp = null;
        Object priceString = null;
        Object fee = null;
        Object audTotal = this.safeString(trade, "audtotal");
        Object costString = this.safeString(trade, "total", audTotal);
        Object side = this.safeString(trade, "side");
        Object amountString = this.safeString(trade, "amount");
        Object marketId = this.safeString(trade, "market");
        Object symbol = this.safeSymbol(marketId, market, "/");
        Object solddate = this.safeInteger(trade, "solddate");
        if (Helpers.isTrue(!Helpers.isEqual(solddate, null)))
        {
            priceString = this.safeString(trade, "rate");
            timestamp = solddate;
        } else
        {
            priceString = Precise.stringDiv(costString, amountString);
            Object createdString = this.safeString(trade, "created");
            timestamp = this.parse8601(createdString);
            Object audfeeExGst = this.safeString(trade, "audfeeExGst");
            Object audGst = this.safeString(trade, "audGst");
            // The transaction fee which consumers pay is inclusive of GST by default
            Object feeCost = Precise.stringAdd(audfeeExGst, audGst);
            Object feeCurrencyId = "AUD";
            fee = new java.util.HashMap<String, Object>() {{
                put( "cost", Coinspot.this.parseNumber(feeCost) );
                put( "currency", Coinspot.this.safeCurrencyCode(feeCurrencyId) );
            }};
        }
        final Object finalTimestamp = timestamp;
        final Object finalPriceString = priceString;
        final Object finalFee = fee;
        return this.safeTrade(new java.util.HashMap<String, Object>() {{
            put( "info", trade );
            put( "id", null );
            put( "symbol", symbol );
            put( "timestamp", finalTimestamp );
            put( "datetime", Coinspot.this.iso8601(finalTimestamp) );
            put( "order", null );
            put( "type", null );
            put( "side", side );
            put( "takerOrMaker", null );
            put( "price", Coinspot.this.parseNumber(finalPriceString) );
            put( "amount", Coinspot.this.parseNumber(amountString) );
            put( "cost", Coinspot.this.parseNumber(costString) );
            put( "fee", finalFee );
        }}, market);
    }

    /**
     * @method
     * @name coinspot#createOrder
     * @description create a trade order
     * @see https://www.coinspot.com.au/api#placebuyorder
     * @param {string} symbol unified symbol of the market to create an order in
     * @param {string} type must be 'limit'
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount how much of currency you want to trade in units of base currency
     * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
     */
    public java.util.concurrent.CompletableFuture<io.github.ccxt.types.Order> createOrder(Object symbol, Object type2, Object side2, Object amount, Object... optionalArgs)
    {
        final Object type3 = type2;
        final Object side3 = side2;
        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {
            Object type = type3;
            Object side = side3;
            Object price = Helpers.getArg(optionalArgs, 0, null);
            Object parameters = Helpers.getArg(optionalArgs, 1, new java.util.HashMap<String, Object>() {{}});
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            if (Helpers.isTrue(Helpers.isEqual(side, null)))
            {
                throw new ArgumentsRequired((String)Helpers.add(this.id, " createOrder() requires a side argument")) ;
            }
            Object sideUpper = ((String)side).toUpperCase();
            if (Helpers.isTrue(Helpers.isEqual(type, "market")))
            {
                throw new ExchangeError((String)Helpers.add(this.id, " createOrder() allows limit orders only")) ;
            }
            Object market = this.market(symbol);
            Object request = new java.util.HashMap<String, Object>() {{
                put( "cointype", Helpers.GetValue(market, "id") );
                put( "amount", amount );
                put( "rate", price );
            }};
            Object response = null;
            if (Helpers.isTrue(Helpers.isEqual(sideUpper, "BUY")))
            {
                response = (this.privatePostMyBuy(this.extend(request, parameters))).join();
            } else if (Helpers.isTrue(Helpers.isEqual(sideUpper, "SELL")))
            {
                response = (this.privatePostMySell(this.extend(request, parameters))).join();
            } else
            {
                throw new NotSupported((String)Helpers.add(this.id, " createOrder only support buy/sell side")) ;
            }
            //
            // status - ok, error
            //
            final Object finalResponse = response;
            return this.safeOrder(new java.util.HashMap<String, Object>() {{
                put( "info", finalResponse );
            }});
        }).thenApply(io.github.ccxt.TypedCores::toOrder);

    }

